import java.util.AbstractSet;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.impl.BlankNodeAllocationScope.IdentityStamp;
import org.eclipse.rdf4j.query.impl.ListBindingSet;
import org.junit.jupiter.api.Test;

class LocalBNodeReferencesNameOrderTest {

	@Test
	void preparationConsumesACustomValueAccessorOnce() {
		var blank = SimpleValueFactory.getInstance().createBNode("fixed");
		var constant = new ValueConstant(blank) {
			int reads;

			@Override
			public Value getValue() {
				reads++;
				return super.getValue();
			}
		};
		assertThat(LocalBNodeReferences.forPreparation(constant, false).ids()).containsExactly("fixed");
		assertThat(constant.reads).isEqualTo(1);
	}

	@Test
	void snapshotsAndSortsAllNamesBeforeAccessingAnyValue() {
		List<String> observed = new ArrayList<>();
		Set<String> liveNames = new LinkedHashSet<>(List.of("z", "a"));
		Set<String> callbackNames = new AbstractSet<>() {
			@Override
			public Iterator<String> iterator() {
				observed.add("iterator");
				return liveNames.iterator();
			}

			@Override
			public int size() {
				return liveNames.size();
			}

			@Override
			public Object[] toArray() {
				observed.add("snapshot");
				return liveNames.toArray();
			}
		};
		var blank = SimpleValueFactory.getInstance().createBNode("fixed");
		var row = new ListBindingSet(List.of()) {
			@Override
			public Set<String> getBindingNames() {
				return callbackNames;
			}

			@Override
			public Value getValue(String name) {
				observed.add("value:" + name);
				if ("a".equals(name)) {
					liveNames.remove("z");
					liveNames.add("injected");
					return blank;
				}
				return null;
			}
		};

		var assignment = new BindingSetAssignment();
		assignment.setBindingSets(List.of(row));
		var analysis = LocalBNodeReferences.analyze(assignment);
		assertThat(analysis.ids()).containsExactly("fixed");
		assertThat(analysis.structure().stream().filter(stamp -> stamp.identity() == row).map(IdentityStamp::state))
				.containsExactly(null, "a", "z");
		assertThat(observed).containsExactly("snapshot", "value:a", "value:z");
	}

	@Test
	void oneNullNameDoesNotCompareButMixedNullNamesFailBeforeReadingAnyValue() {
		List<String> observed = new ArrayList<>();
		var assignment = new BindingSetAssignment();
		assignment.setBindingSets(List.of(nullNameRow(observed, (String) null)));
		LocalBNodeReferences.analyze(assignment);
		assertThat(observed).containsExactly((String) null);

		observed.clear();
		assignment.setBindingSets(List.of(nullNameRow(observed, "z", null)));
		assertThatThrownBy(() -> LocalBNodeReferences.analyze(assignment)).isInstanceOf(NullPointerException.class);
		assertThat(observed).isEmpty();
	}

	private static ListBindingSet nullNameRow(List<String> observed, String... names) {
		return new ListBindingSet(List.of()) {
			@Override
			public Set<String> getBindingNames() {
				return new LinkedHashSet<>(Arrays.asList(names));
			}

			@Override
			public Value getValue(String name) {
				observed.add(name);
				return null;
			}
		};
	}
}
